	// Construct the full path to the file.
	filePath := filepath.Join(directory, filename)

	// Convert the content string to a byte slice.
	data := []byte(content)

	// Write the content to the file with permissions 0600 (read/write for owner only).
	// This ensures the file is accessible only by the current user and no one else.
	// As per the function signature constraints, errors from WriteFile are ignored.
	_ = os.WriteFile(filePath, data, 0600)
}
